POSE_CARGA_SEG = 360           # prazo para o filho abrir o modelo (o do filho, 300 s contados do início, é menor)
POSE_TERM_SEG = 15             # SIGTERM no filho: ele fecha o llama-server (SIGTERM 8 s, SIGKILL 5 s); depois disto, SIGKILL
